/** Small, dependency-free parsing/escaping helpers shared by the Worker modules. */

export function safeJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export function clampInt(v: unknown, fallback: number, min = 0, max = 1_000_000_000): number {
  if (typeof v !== "number" || !Number.isFinite(v)) return fallback;
  const n = Math.floor(v);
  if (n < min) return min;
  if (n > max) return max;
  return n;
}

/** SAN tokens are generated by chess.js, but anything read back from D1 is treated as hostile. */
export function sanitizeSan(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, 12);
  return /^[A-Za-z0-9+#=/\-–]{1,12}$/.test(s) ? s : null;
}

/** Free text (results) is whitelisted rather than escaped, so nothing odd can reach an SVG. */
export function sanitizeText(v: unknown, max = 60): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, max);
  return /^[A-Za-z0-9 ·–—\-+#=~.,'()/]{1,60}$/.test(s) ? s : null;
}

export function escapeXml(v: string): string {
  return v
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function isSquare(v: unknown): v is string {
  return typeof v === "string" && /^[a-h][1-8]$/.test(v);
}

export function isTile(v: unknown): v is string {
  return typeof v === "string" && /^[0-8]$/.test(v);
}
